            // If the current element is not equal to the next element
            if (i < numbers.size() - 1 && numbers.get(i) != numbers.get(i + 1)) {
                // Add the current element to the new array list
                newList.add(numbers.get(i));
            }
        }
        // If the last element is not equal to the element before it
        if (numbers.get(numbers.size() - 1) != numbers.get(numbers.size() - 2)) {
            // Add the last element to the new array list
            newList.add(numbers.get(numbers.size() - 1));
        }
        // Return the new array list
        return newList;

