                    result.set(i, "Six");
                    break;
                case "7":
                    result.set(i, "Seven");
                    break;
                case "8":
                    result.set(i, "Eight");
                    break;
                case "9":
                    result.set(i, "Nine");
                    break;
            }
        }
        return result;

