            return true;
        }
        int i = 0;
        int j = 0;
        while (i < arr.size() - 1) {
            if (arr.get(i) > arr.get(i + 1)) {
                j = i;
                while (j < arr.size() - 1) {
                    if (arr.get(j) > arr.get(j + 1)) {
                        j++;
