    // - The substring after the dot should be one of these: ['txt', 'exe', 'dll']
    // Examples:
    // >>> fileNameCheck(("example.txt"))
    // ("Yes")
    // >>> fileNameCheck(("1example.dll"))
    // ("No")
    public static String fileNameCheck(String file_name) {
        String[] parts = file_name.split("\\.");
        if(parts.length != 2) return "No";
        if(parts[0].length() == 0) return "No";
        if(parts[1].length() == 0) return "No";
        if(parts[1].length() != 3) return "No";
        if(!parts[1].equals("txt") && !parts[1].equals("exe") && !parts[1].equals("dll")) return "No";
