    // expression and return the evaluation of this expression.
    // The basic algebra operations:
    // Addition ( + ) 
    // Subtraction ( - ) 
    // Multiplication ( * ) 
    // Floor division ( // ) 
    // Exponentiation ( ** ) 
    // Example:
    // operator['+', '*', '-']
    // array array list = [2, 3, 4, 5]
    // result = 2 + 3 * 4 - 5
    // => result = 9
    // Note:
    // The length of operator array list is equal to the length of operand array list minus one.
    // Operand is an array array list of of non-negative integers.
    // Operator array list has at least one operator, and operand array list has at least two operands.
    public static long doAlgebra(ArrayList<String> op, ArrayList<Long> operand) {
        int i = 0;
        long result = 0;
        long a = 0;
        long b = 0;
        while(i < op.size()){
            if(op.get(i).equals("+")){
                a = operand.get(i);
                b = operand.get(i+1);
                result = a + b;
                operand.set(i+1, result);
                op.remove(i);
                operand.remove(i);
                i = 0;
            }
            else if(op.get(i).equals("-")){
                a = operand.get(i);
                b = operand.get(i+1);
                result = a - b;
                operand.set(i+1, result);
                op.remove(i);
                operand.remove(i);
                i = 0;
            }
            else if(op.get(i).equals("*")){
                a = operand.get(i);
                b = operand.get(i+1);
                result = a * b;
                operand.set(i+1, result);
                op.remove(i);
                operand.remove(i);
                i = 0;
            }
            else if(op.get(i).equals("/")){
                a = operand.get(i);
                b = operand.get(i+1);
                result = a / b;
                operand.set(i+1, result);
                op.remove(i);
                operand.remove(i);
                i = 0;
            }
            else if(op.get(i).equals("**")){
                a = operand.get(i);
                b = operand.get(i+1);
                result = (long) Math.pow(a, b);
                operand.set(i+1, result);
                op.remove(i);
                operand.remove(i);
                i = 0;
            }
            i++;
        }
        return result;

